import { useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '../ui/button';

import type { MonthYearCount } from '~/hooks/useBluebirdMonthsYears';
import { Box } from 'styled-system/jsx';

interface LoadingIndicatorProps {
  isLoading: boolean;
  hasMore: boolean;
  onIntersect?: () => void;
  selectedMonthYear?: string;
  monthsYears?: MonthYearCount[];
  onMonthYearClick?: (monthYear: string) => void;
}

export function LoadingIndicator({
  isLoading,
  hasMore,
  onIntersect,
  selectedMonthYear,
  monthsYears,
  onMonthYearClick
}: LoadingIndicatorProps) {
  const loadingRef = useRef<HTMLDivElement>(null);
  const { t } = useTranslation();

  useEffect(() => {
    if (!loadingRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !isLoading) {
          onIntersect?.();
        }
      },
      {
        rootMargin: '0px',
        threshold: 0.1
      }
    );

    observer.observe(loadingRef.current);

    return () => {
      observer.disconnect();
    };
  }, [isLoading, hasMore, onIntersect]);

  return (
    <Box
      ref={loadingRef}
      mb={{ mdDown: '20' }}
      p="5"
      color="fg.muted"
      textAlign="center"
      fontSize="sm"
      fontStyle="italic"
    >
      {isLoading
        ? t('bluebird.loadingIndicator.loadingMoreTweets')
        : hasMore
          ? t('bluebird.loadingIndicator.scrollDownToLoadMore')
          : monthsYears && selectedMonthYear && monthsYears.length > 0
            ? (() => {
                const currentIndex = monthsYears.findIndex(
                  (item) => item.monthYear === selectedMonthYear
                );
                const nextMonthYear = monthsYears[currentIndex + 1]?.monthYear;
                if (nextMonthYear) {
                  return (
                    <Button
                      variant="link"
                      onClick={() => onMonthYearClick?.(nextMonthYear)}
                      cursor="pointer"
                    >
                      {t('bluebird.loadingIndicator.noMoreTweetsForMonth', {
                        monthYear: new Date(nextMonthYear).toLocaleString('en-US', {
                          month: 'long',
                          year: 'numeric'
                        })
                      })}
                    </Button>
                  );
                } else {
                  return t('bluebird.loadingIndicator.noMoreTweets');
                }
              })()
            : t('bluebird.loadingIndicator.noMoreTweets')}
    </Box>
  );
}
