import { useEffect, useRef, useMemo, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import { useInfiniteQuery } from '@tanstack/react-query';
import { decompress } from 'compress-json';
import { useTranslation } from 'react-i18next';
import type { Event, TweetGroup } from '~/types/bluebird';
import { Box, Center } from 'styled-system/jsx';
import { GroupedTweet } from '~/components/bluebird/GroupedTweet';
import { useToaster } from '~/context/ToasterContext';
import { useScrollTracking } from '~/hooks/useScrollTracking';
import { EventDisplay } from '~/components/bluebird/EventDisplay';
import { parseUtcString } from '~/utils/date';
import { LoadingIndicator } from '~/components/bluebird/LoadingIndicator';
import type { MonthYearCount } from '~/hooks/useBluebirdMonthsYears';
import { LoadPreviousTweets } from '~/components/bluebird/LoadPreviousTweets';
import { getAssetUrl } from '~/utils/assets';
import { Button } from '~/components/ui/button';

interface StaticReadingModeProps {
  lastReadTweetId?: string | null;
  onCurrentMonthYearChange: (monthYear: string | null) => void;
  events: Event[];
  useEnglishName?: boolean;
  monthsYears: MonthYearCount[];
  tweetPath?: string;
  onLoadingStateChange: (show: boolean) => void;
}

export const LOCAL_STORAGE_KEY = 'bluebirdReadingModeLastReadTweetIdStatic';

const fetchTweetGroups = async ({
  pageParam,
  tweetPath = '/tweets'
}: {
  pageParam: string;
  tweetPath?: string;
}): Promise<TweetGroup[]> => {
  const response = await fetch(
    getAssetUrl(`${tweetPath}/${pageParam}.json?cache=${new Date().valueOf()}`)
  );
  if (!response.ok) {
    throw new Error('Network response was not ok');
  }
  const res = await response.json();
  return !('tweets' in res[0]) ? decompress(res) : res;
};

export function StaticReadingMode({
  lastReadTweetId,
  onCurrentMonthYearChange,
  events,
  useEnglishName,
  monthsYears,
  tweetPath,
  onLoadingStateChange
}: StaticReadingModeProps) {
  const parentRef = useRef<HTMLDivElement>(null);
  const { toast } = useToaster();
  const { t } = useTranslation();
  const [autoScrolled, setAutoScrolled] = useState(!lastReadTweetId);
  const [isScrolling, setIsScrolling] = useState(false);
  const [scrollToId, setScrollToId] = useState<string | null>(null);

  const availableMonths = useMemo(() => monthsYears.map((m) => m.monthYear), [monthsYears]);

  const initialMonth = useMemo(() => {
    if (!lastReadTweetId) {
      return availableMonths[0];
    }
    const month = [...monthsYears].reverse().find((m) => lastReadTweetId >= m.firstTweetId);
    return month ? month.monthYear : availableMonths[0];
  }, [lastReadTweetId, monthsYears, availableMonths]);

  const {
    data,
    fetchNextPage,
    fetchPreviousPage,
    hasNextPage,
    hasPreviousPage,
    isFetchingNextPage,
    isFetchingPreviousPage,
    isLoading,
    refetch,
    isRefetching
  } = useInfiniteQuery({
    queryKey: ['static-tweets', tweetPath, initialMonth],
    queryFn: ({ pageParam }) => fetchTweetGroups({ pageParam, tweetPath }),
    initialPageParam: initialMonth,
    getNextPageParam: (_lastPage, _allPages, lastPageParam) => {
      const currentIndex = availableMonths.indexOf(lastPageParam);
      if (currentIndex > -1 && currentIndex < availableMonths.length - 1) {
        return availableMonths[currentIndex + 1];
      }
      return undefined;
    },
    getPreviousPageParam: (_firstPage, _allPages, firstPageParam) => {
      const currentIndex = availableMonths.indexOf(firstPageParam);
      if (currentIndex > 0) {
        return availableMonths[currentIndex - 1];
      }
      return undefined;
    }
  });

  const handleRefresh = () => {
    refetch();
  };

  const groupedTweets = data?.pages.flatMap((page) => page) || [];

  const combinedData = useMemo(() => {
    if (groupedTweets.length === 0) {
      return [];
    }

    const latestTweetTimestamp = Math.max(
      ...groupedTweets.map((g) => parseUtcString(g.group_end_time).getTime())
    );
    const oldestTweetTimestamp = Math.min(
      ...groupedTweets.map((g) => parseUtcString(g.group_start_time).getTime())
    );

    const mappedTweets = groupedTweets.map((item) => ({
      id: item.tweets[0].id,
      type: 'groupedTweet' as const,
      data: item,
      timestamp: parseUtcString(item.group_start_time).getTime()
    }));

    const filteredEvents = events.filter((event) => {
      const eventTs = new Date(event.eventDate).getTime();
      return eventTs >= oldestTweetTimestamp && eventTs <= latestTweetTimestamp;
    });

    const mappedEvents = filteredEvents.map((event) => ({
      id: event.id,
      type: 'event' as const,
      data: event,
      timestamp: new Date(event.eventDate).getTime()
    }));

    const allData = [...mappedTweets, ...mappedEvents].sort((a, b) => a.timestamp - b.timestamp);

    return allData;
  }, [groupedTweets, events]);

  const virtualizer = useVirtualizer({
    count: combinedData.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 250, // Estimate average item size
    overscan: 2
  });

  const virtualItems = virtualizer.getVirtualItems();

  const listOffset = hasPreviousPage ? 96 : 0;

  const doubleScrollToIndex = (
    index: number,
    options?: { callback?: () => void; isPrevPage?: boolean }
  ) => {
    const { callback, isPrevPage } = options || {};
    const scroll = () => {
      if (index !== -1) {
        const offset = virtualizer.getOffsetForIndex(index, 'start') as [number, 'start'];
        const scrollOffset = isPrevPage ? offset[0] - 96 : offset[0] + listOffset;
        virtualizer.scrollToOffset(scrollOffset, {
          align: 'start',
          behavior: 'auto'
        });
      }
    };

    setTimeout(() => {
      scroll();
      setTimeout(() => {
        scroll();
        setIsScrolling(false);
        if (callback) {
          callback();
        }
      });
    });
  };

  const handleLoadPrevious = () => {
    if (hasPreviousPage && !isFetchingPreviousPage) {
      setIsScrolling(true);
      if (combinedData.length > 0) {
        const firstItemId = combinedData[0].id;
        fetchPreviousPage().then(() => {
          setScrollToId(firstItemId);
        });
      } else {
        fetchPreviousPage();
      }
    }
  };

  useEffect(() => {
    if (scrollToId) {
      const index = combinedData.findIndex((item) => item.id === scrollToId);
      if (index !== -1) {
        doubleScrollToIndex(index, { isPrevPage: true });
        setScrollToId(null);
      }
    }
  }, [scrollToId, combinedData]);

  useEffect(() => {
    if (isLoading || !lastReadTweetId || autoScrolled) {
      return;
    }

    const index = combinedData.findIndex((item) =>
      item.type === 'groupedTweet'
        ? item.data.tweets.some((t) => t.id === lastReadTweetId)
        : item.id === lastReadTweetId
    );

    if (index !== -1) {
      doubleScrollToIndex(index, { callback: () => setAutoScrolled(true) });
    } else {
      setAutoScrolled(true);
    }
  }, [lastReadTweetId, isLoading, combinedData, virtualizer, listOffset, autoScrolled]);

  useEffect(() => {
    setAutoScrolled(!lastReadTweetId);
  }, [lastReadTweetId]);

  useEffect(() => {
    if (!virtualItems.length) return;

    const lastItem = virtualItems[virtualItems.length - 1];

    if (lastItem.index >= combinedData.length - 1 && hasNextPage && !isFetchingNextPage) {
      fetchNextPage();
    }
  }, [virtualItems, hasNextPage, isFetchingNextPage, fetchNextPage, combinedData.length]);

  useScrollTracking({
    parentRef,
    virtualizer,
    data: combinedData,
    localStorageKey: LOCAL_STORAGE_KEY,
    onCurrentMonthYearChange,
    offset: listOffset
  });

  // Report loading state to parent
  useEffect(() => {
    onLoadingStateChange(isLoading || isScrolling || isRefetching || isFetchingPreviousPage);
  }, [isLoading, isScrolling, onLoadingStateChange, isRefetching, isFetchingPreviousPage]);

  const onCopy = (text: string, type: 'text' | 'link') => {
    navigator.clipboard.writeText(text).then(
      () => {
        toast?.(t('bluebird.readingMode.copiedToClipboard', { type }));
      },
      (err) => {
        toast?.(t('bluebird.readingMode.failedToCopy'));
        console.error('Could not copy text: ', err);
      }
    );
  };

  return (
    <>
      <Box
        layerStyle="contentHeight"
        ref={parentRef}
        position="relative"
        overscrollBehavior="contain"
        overflowY="auto"
      >
        {hasPreviousPage && (
          <LoadPreviousTweets
            loadPrevious={handleLoadPrevious}
            hasPreviousPage={hasPreviousPage}
            isFetchingPreviousPage={isFetchingPreviousPage}
          />
        )}
        <Box style={{ height: `${virtualizer.getTotalSize()}px` }} position="relative">
          {virtualItems.map((virtualItem) => {
            const item = combinedData[virtualItem.index];
            return (
              <Box
                key={virtualItem.key}
                data-index={virtualItem.index}
                ref={virtualizer.measureElement}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  transform: `translateY(${virtualItem.start}px)`
                }}
              >
                {item.type === 'groupedTweet' && (
                  <GroupedTweet group={item.data} onCopy={onCopy} useEnglishName={useEnglishName} />
                )}
                {item.type === 'event' && (
                  <EventDisplay event={item.data} useEnglish={useEnglishName} />
                )}
              </Box>
            );
          })}
        </Box>
        {isFetchingNextPage && <LoadingIndicator isLoading={true} hasMore={true} />}
        {!hasNextPage && !isLoading && (
          <Center py="4">
            <Button onClick={handleRefresh} disabled={isRefetching}>
              {isRefetching
                ? t('bluebird.readingMode.refreshing')
                : t('bluebird.readingMode.refresh')}
            </Button>
          </Center>
        )}
      </Box>
    </>
  );
}
