import { TweetSkeleton } from './TweetSkeleton';
import { Stack } from 'styled-system/jsx';

interface SkeletonOverlayProps {
  show: boolean;
}

export function SkeletonOverlay({ show }: SkeletonOverlayProps) {
  return (
    <Stack
      zIndex="10"
      position="absolute"
      top="0"
      left="0"
      width="full"
      height="full"
      bg="bg.default"
      opacity={show ? 1 : 0}
      overflow="hidden"
      transition="opacity 0.1s ease-out"
      pointerEvents={show ? 'auto' : 'none'}
    >
      {Array.from({ length: 5 }).map((_, i) => (
        <TweetSkeleton key={i} />
      ))}
    </Stack>
  );
}
